// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product, Fixed18, PackedFixed18, PackedUFixed18, UFixed18, IOracleProvider, JumpRateUtilizationCurve, PayoffDefinition, PayoffDefinitionLib, IProduct} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    address constant OWNER = address(0xA11CE);
    MockController ctrl;

    function setUp() public {
        ctrl = new MockController(OWNER);
        MockOracle oracle = new MockOracle();
        c = new Product();

        PayoffDefinition memory pd = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(0),
            PayoffDefinitionLib.PayoffDirection(0),
            bytes30(0)
        );

        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedUFixed18.wrap(0)
        );

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: pd,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e18),
            utilizationCurve: curve
        });

        vm.prank(address(ctrl));
        c.initialize(info);
    }

    function testFuzz_property(address caller, uint256 newFee) public {
        vm.assume(caller != OWNER);
        vm.assume(caller != address(ctrl));
        vm.assume(caller != address(c));
        newFee = bound(newFee, 1, 1e18);

        // A caller that is NOT the coordinator owner attempts to change the fee.
        vm.prank(caller);
        try c.updateFundingFee(UFixed18.wrap(newFee)) {
            // succeeded
        } catch {
            // reverted: fine for the reference
        }

        // General rule: a non-owner can never move the funding fee off its stored value.
        assertTrue(UFixed18.unwrap(c.fundingFee()) == 0, "non-owner changed funding fee");
    }
}

contract MockController {
    address public immutable coordinatorOwner;

    constructor(address owner_) {
        coordinatorOwner = owner_;
    }

    function coordinatorFor(IProduct) external pure returns (uint256) {
        return 1;
    }

    function owner(uint256) external view returns (address) {
        return coordinatorOwner;
    }

    function paused() external pure returns (bool) {
        return false;
    }
}

contract MockOracle {
    function _zero() internal pure returns (IOracleProvider.OracleVersion memory ov) {
        ov = IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }

    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return _zero();
    }

    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return _zero();
    }

    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return _zero();
    }
}
